import {safeAvatar} from './trade-model.mjs';
import {supabase,currentUser,login,saveSettings,loadSettings} from './auth-client.mjs';
import {DOJO_ELEMENTS,emptyDojoLevels,profileContactValues} from './account-model.mjs';
const $=id=>document.getElementById(id);let user=null,levels=emptyDojoLevels(),data,revision=0,loading=false;
const root=new URL('./tatari-data/',import.meta.url),el=(tag,value)=>{const n=document.createElement(tag);if(value!==undefined)n.textContent=value;return n;};
function paintSharing(id,revealed){const b=$(id);b.textContent=revealed?'Revealed':'Hidden';b.setAttribute('aria-pressed',String(revealed));b.setAttribute('aria-label',(id==='share-game-id'?'In-Game ID':'Discord Username')+' sharing: '+(revealed?'Revealed':'Hidden'));}
for(const id of ['share-discord'])$(id).onclick=()=>{paintSharing(id,$(id).getAttribute('aria-pressed')!=='true');$('profile-status').textContent='Unsaved changes';};
function badgePickers(){const holder=$('account-dojos');holder.replaceChildren();holder.className='account-dojo-elements';for(const [element,label] of DOJO_ELEMENTS){const group=el('div'),button=el('button'),icon=el('img');button.type='button';button.className='account-dojo-element';button.setAttribute('aria-label',label+' Dojo Badges');button.setAttribute('aria-pressed',String(levels[element]>0));icon.src=new URL(data.units.find(u=>u.element===Number(element)).elementImage,root);icon.alt=label;button.append(icon,el('span','Level '+levels[element]));
 const dialog=el('dialog');dialog.className='account-badge-dialog';dialog.setAttribute('aria-label',label+' Dojo Badges');const header=el('div'),close=el('button'),cross=el('img');header.className='badge-dialog-heading';close.className='dialog-close';close.type='button';close.setAttribute('aria-label','Close');cross.src=new URL('images/close-x.png',root);cross.alt='';close.append(cross);close.onclick=()=>dialog.close();header.append(el('h2',label+' Dojo Badges'),close);const row=el('div');row.className='account-badge-options';for(const [i,b] of data.badges.filter(b=>b.element===Number(element)).sort((a,b)=>a.id-b.id).entries()){const choice=el('button'),picture=el('img');choice.type='button';choice.setAttribute('aria-label',label+' badge '+(i+1)+' of 7');choice.setAttribute('aria-pressed',String(i<levels[element]));picture.src=new URL(b.image,root);picture.alt=b.name;choice.append(picture,el('span',(i+1)+' / 7'));choice.onclick=()=>{levels[element]=levels[element]===i+1?0:i+1;dialog.close();badgePickers();$('save-status').textContent='Unsaved changes';};row.append(choice);}dialog.append(header,row);button.onclick=()=>dialog.showModal();group.append(button,dialog);holder.append(group);}}
async function refresh(){if(!data)return;const id=++revision;try{user=await currentUser();if(id!==revision)return;$('signed-out').hidden=!!user;$('signed-in').hidden=!user;if(!user)return;$('profile-name').value=user.user_metadata?.full_name||user.user_metadata?.name||'Player';$('game-id').value='';$('discord-username').value='';$('trade-listing-enabled').checked=false;$('public-album-enabled').checked=false;paintSharing('share-discord',false);$('account-status').textContent='Loading your settings…';loading=true;$('save-dojos').disabled=true;$('save-profile').disabled=true;const profile=await supabase.from('profiles').select('*').eq('user_id',user.id).maybeSingle();if(profile.error)throw profile.error;if(id!==revision)return;if(profile.data){$('profile-name').value=profile.data.display_name;$('game-id').value=profile.data.game_id;$('discord-username').value=profile.data.discord_username??'';$('trade-listing-enabled').checked=profile.data.trade_enabled===true;$('public-album-enabled').checked=profile.data.album_public===true;paintSharing('share-discord',profile.data.share_discord===true);}levels=await loadSettings();if(id!==revision)return;badgePickers();$('account-status').textContent='';$('save-dojos').disabled=false;$('save-profile').disabled=false;}catch(error){$('account-status').textContent='Account settings are unavailable. '+error.message;}finally{loading=false;}}
for(const provider of ['discord'])$(provider+'-login').onclick=async()=>{try{$('login-status').textContent='Opening '+provider+'…';await login(provider);}catch(error){$('login-status').textContent=error.message;}};
$('logout').onclick=async()=>{const {error}=await supabase.auth.signOut({scope:'local'});if(error){$('account-status').textContent=error.message;return;}await refresh();};
$('profile-form').onsubmit=async e=>{e.preventDefault();if(!user||loading)return;const displayName=$('profile-name').value.trim();if(!displayName){$('profile-status').textContent='Enter a display name.';return;}$('save-profile').disabled=true;try{const {error}=await supabase.from('profiles').upsert({user_id:user.id,trade_enabled:$('trade-listing-enabled').checked,album_public:$('public-album-enabled').checked,avatar_url:safeAvatar(user.user_metadata?.avatar_url),...profileContactValues({displayName,gameId:$('game-id').value,discordUsername:$('discord-username').value,shareGameId:true,shareDiscord:$('share-discord').getAttribute('aria-pressed')==='true'})},{onConflict:'user_id'});if(error)throw error;$('profile-status').textContent='Profile saved.';}catch(error){$('profile-status').textContent=['PGRST204','42703'].includes(error.code)?'Profile settings need the latest database update before they can be saved.':error.message;}finally{$('save-profile').disabled=false;}};
$('save-dojos').onclick=async()=>{if(loading)return;$('save-dojos').disabled=true;try{await saveSettings(levels);$('save-status').textContent='Dojo settings saved.';}catch(error){$('save-status').textContent=error.message;}finally{$('save-dojos').disabled=false;}};
supabase.auth.onAuthStateChange(()=>setTimeout(refresh,0));
try{const response=await fetch(new URL('roster.json',root));if(!response.ok)throw Error('Tatari assets could not load.');data=await response.json();badgePickers();await refresh();}catch(error){$('account-status').textContent=error.message;}

window.addEventListener('game-uid-saved',refresh);
